<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';
use FMonitor2\InstallationProcess\{BitrixWorkforceHistorySchemaMigration,MariaDbWorkforceSynchronization,WorkforceCatalogSchemaMigration};use FMonitor2\Workforce\{BitrixWorkforceDeliveryBatch,BitrixWorkforceDeliveryClient,BitrixWorkforceDeliveryResult,BitrixWorkforceDeliveryReason};
final class SyntheticDelivery implements BitrixWorkforceDeliveryClient{public function __construct(private?array$rows,private?BitrixWorkforceDeliveryReason$reason=null){}public function fetch():BitrixWorkforceDeliveryResult{return$this->reason?new BitrixWorkforceDeliveryResult($this->reason,1,1,null):new BitrixWorkforceDeliveryResult(null,1,1,new BitrixWorkforceDeliveryBatch(count($this->rows??[]),$this->rows??[]));}}
function worker(string$id,string$email,string$xing,bool$active,?string$from=null):array{return['ID'=>$id,'ACTIVE'=>$active,'LAST_NAME'=>'Иванов','NAME'=>'Иван','SECOND_NAME'=>'','WORK_POSITION'=>'Монтажник','EMAIL'=>$email,'UF_XING'=>$xing,'UF_DEPARTMENT'=>[71],'UF_EMPLOYMENT_DATE'=>$from];}
$h=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$u=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$pw=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_wsync_'.bin2hex(random_bytes(4));$a=new mysqli($h,$u,$pw,'',$port);$a->query("CREATE DATABASE `$name` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($h,$u,$pw,$name,$port);$p='ws_';
try{WorkforceCatalogSchemaMigration::apply($db,$p);BitrixWorkforceHistorySchemaMigration::apply($db,$p);$sync=new MariaDbWorkforceSynchronization($db,$p);$one=[worker('501','tab001042@example.test','001042',true,null),worker('502','other@example.test','1043',false,'2020-01-02')];$r=$sync->run(new SyntheticDelivery($one),'018f47ba-2f6d-4f80-8f42-0b37657fd111','2026-09-07T10:00:00+03:00');assertSameValue(['completed',2,2],[$r['status'],$r['delivered'],$r['materialChanges']],'first full batch publishes');$row=$db->query("SELECT employed_from FROM `{$p}fm2_workforce_catalog` WHERE installer_tab_id=1042")->fetch_assoc();assertSameValue(null,$row['employed_from'],'unknown start stays null');$r=$sync->run(new SyntheticDelivery($one),'018f47ba-2f6d-4f80-8f42-0b37657fd112','2026-09-07T11:00:00+03:00');assertSameValue(0,$r['materialChanges'],'identical repeat adds no observations');assertSameValue(2,(int)$db->query("SELECT COUNT(*) n FROM `{$p}fm2_workforce_observations`")->fetch_assoc()['n'],'repeat preserves history');$conflict=$sync->run(new SyntheticDelivery([worker('501','tab9999@example.test','9999',true)]),'018f47ba-2f6d-4f80-8f42-0b37657fd119','2026-09-07T11:30:00+03:00');assertSameValue('IDENTITY_CONFLICT',$conflict['reason'],'existing delivery identity cannot move to another employee number');assertSameValue(0,(int)$db->query("SELECT COUNT(*) n FROM `{$p}fm2_workforce_catalog` WHERE installer_tab_id=9999")->fetch_assoc()['n'],'identity conflict publishes no row');$r=$sync->run(new SyntheticDelivery([$one[0]]),'018f47ba-2f6d-4f80-8f42-0b37657fd113','2026-09-07T12:00:00+03:00');assertSameValue([1,1],[$r['missing'],$r['materialChanges']],'missing worker is reconciled');$missing=$db->query("SELECT employment_status,reconciliation_state FROM `{$p}fm2_workforce_catalog` WHERE installer_tab_id=1043")->fetch_assoc();assertSameValue(['dismissed','missing_from_delivery'],array_values($missing),'missing is not a new dismissal');$before=(int)$db->query("SELECT COUNT(*) n FROM `{$p}fm2_workforce_observations`")->fetch_assoc()['n'];$failed=$sync->run(new SyntheticDelivery(null,BitrixWorkforceDeliveryReason::TransportFailed),'018f47ba-2f6d-4f80-8f42-0b37657fd114');assertSameValue('failed',$failed['status'],'partial delivery failure is audited with native clock');assertSameValue($before,(int)$db->query("SELECT COUNT(*) n FROM `{$p}fm2_workforce_observations`")->fetch_assoc()['n'],'failed delivery publishes nothing');echo"workforce_synchronization_manual_pilot_test: PASS\n";}finally{$db->close();$a->query("DROP DATABASE IF EXISTS `$name`");$a->close();}
